import cors from "cors"
import { config } from "wasp/server"
import { type MiddlewareConfigFn } from "wasp/server"

export const serverMiddlewareFn: MiddlewareConfigFn = (middlewareConfig) => {
  // Extends the allowed CORS origins so requests from the local origin http://localhost:5000 are accepted,
  // while keeping the existing/default allowed origins (including the local client at http://localhost:3000) working.
  middlewareConfig.set("cors", cors({ origin: [...config.allowedCORSOrigins, "http://localhost:5000"] }))

  // Adds a custom middleware entry that sets the response header X-Global: enabled on responses.
  middlewareConfig.set("x-global", (req, res, next) => {
    res.setHeader("X-Global", "enabled");
    next();
  });

  return middlewareConfig;
}

export const apiNamespaceMiddleware: MiddlewareConfigFn = (middlewareConfig) => {
  // Apply a per-path (namespace) middleware to everything under /api that sets the response header X-Api-Namespace: v1.
  middlewareConfig.set("x-api-namespace", (req, res, next) => {
    res.setHeader("X-Api-Namespace", "v1");
    next();
  });
  return middlewareConfig;
}

import express from "express"
import { type MiddlewareConfigFn } from "wasp/server"
import { type Status, type Echo } from "wasp/server/api"

export const getStatus: Status = (req, res) => {
  res.status(200).json({ status: "ok" });
}

export const echoHandler: Echo = (req, res) => {
  const body = req.body;
  const bytes = Buffer.isBuffer(body) ? body.length : 0;
  res.status(200).json({ bytes });
}

export const echoMiddleware: MiddlewareConfigFn = (middlewareConfig) => {
  // Replaces the default JSON body parser with a raw body parser (so the handler receives the unparsed request body as raw bytes)
  middlewareConfig.delete("express.json");
  middlewareConfig.set("express.raw", express.raw({ type: "*/*" }));

  // Sets the response header X-Echo: raw on that route only.
  middlewareConfig.set("x-echo", (req, res, next) => {
    res.setHeader("X-Echo", "raw");
    next();
  });

  return middlewareConfig;
}

app customMiddleware {
  wasp: {
    version: "^0.21.1"
  },
  title: "custom-middleware",
  head: [
    "<link rel='icon' href='/favicon.ico' />",
  ],
  server: {
    middlewareConfigFn: import { serverMiddlewareFn } from "@src/server/middleware.js"
  }
}

route RootRoute { path: "/", to: MainPage }
page MainPage {
  component: import { MainPage } from "@src/MainPage"
}

apiNamespace apiNamespace {
  middlewareConfigFn: import { apiNamespaceMiddleware } from "@src/server/middleware.js",
  path: "/api"
}

api status {
  httpRoute: (GET, "/api/status"),
  fn: import { getStatus } from "@src/server/apis.js",
  auth: false
}

api echo {
  httpRoute: (POST, "/api/echo"),
  fn: import { echoHandler } from "@src/server/apis.js",
  middlewareConfigFn: import { echoMiddleware } from "@src/server/apis.js",
  auth: false
}

